  'Enter a valid account number (9–18 digits)' => 'சரியான கணக்கு எண்ணை உள்ளிடவும் (9–18 இலக்கங்கள்)',
  'Enter IFSC code' => 'IFSC குறியீட்டை உள்ளிடவும்',
  'Enter a valid SWIFT / BIC code' => 'சரியான SWIFT / BIC குறியீட்டை உள்ளிடவும்',
  'Enter a valid IFSC code (e.g. SBIN0001234)' => 'சரியான IFSC குறியீட்டை உள்ளிடவும் (எ.கா. SBIN0001234)',
  'Enter the expected stipend for a paid internship (₹8,000 – ₹5,00,000)' => 'ஊதியத்துடன் கூடிய இன்டர்ன்ஷிப்பிற்கு எதிர்பார்க்கும் உதவித்தொகையை உள்ளிடவும் (₹8,000 – ₹5,00,000)',
  'Please accept all terms & conditions' => 'அனைத்து விதிமுறைகள் & நிபந்தனைகளையும் ஏற்கவும்',
  'File could not be uploaded' => 'கோப்பைப் பதிவேற்ற முடியவில்லை',
  'File is larger than 5MB' => 'கோப்பு 5MB-ஐ விடப் பெரியது',
  'Only PDF, DOC, DOCX, JPG or PNG files' => 'PDF, DOC, DOCX, JPG அல்லது PNG கோப்புகள் மட்டும்',
  'Only PDF, DOC or DOCX files' => 'PDF, DOC அல்லது DOCX கோப்புகள் மட்டும்',
  'Photo could not be uploaded' => 'புகைப்படத்தைப் பதிவேற்ற முடியவில்லை',
